let state={course:null,topic:null,questions:[],answers:[],index:0,seconds:0,timer:null,lastResult:null};
const RESULTS_KEY='fuo_results_v3';
const PROFILE_KEY='fuo_profile_v3';
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const USERS_KEY='fuo_users_v4';
const SESSION_KEY='fuo_session_v4';
function getUsers(){return JSON.parse(localStorage.getItem(USERS_KEY)||'{}')}
function saveUsers(users){localStorage.setItem(USERS_KEY,JSON.stringify(users))}
function getProfile(){const email=localStorage.getItem(SESSION_KEY);if(!email)return null;const u=getUsers()[email];return u?{name:u.name,email:u.email}:null}
function saveProfile(profile){const users=getUsers();const key=profile.email.toLowerCase();users[key]={...(users[key]||{}),...profile};saveUsers(users);localStorage.setItem(SESSION_KEY,key)}
function session(){return getProfile()}
async function hashPassword(password){const data=new TextEncoder().encode(password);const hash=await crypto.subtle.digest('SHA-256',data);return Array.from(new Uint8Array(hash)).map(b=>b.toString(16).padStart(2,'0')).join('')}
function showAuth(mode='login'){const login=$('loginForm'),reg=$('registerForm');login.classList.toggle('hidden',mode!=='login');reg.classList.toggle('hidden',mode!=='register');$('authTitle').textContent=mode==='login'?'Welcome back':'Create your account';$('authSubtitle').textContent=mode==='login'?'Sign in to continue to your test-drilling dashboard.':'Create your student account to start practising.';$('loginError').textContent='';$('registerError').textContent=''}
function enterApp(){const s=session();if(!s){$('authScreen').classList.remove('hidden');$('app').classList.add('hidden');showAuth('login');return}$('authScreen').classList.add('hidden');$('app').classList.remove('hidden');$('welcomeName').textContent=' — '+esc(s.name);renderCourses();updateStats();showPage('dashboardPage')}
function showPage(id){document.querySelectorAll('.page').forEach(p=>p.classList.add('hidden'));const page=$(id);if(page)page.classList.remove('hidden');if(id==='dashboardPage')updateStats();if(id==='resultsHistoryPage')renderHistory();if(id==='profilePage')renderProfile()}
function renderCourses(){const g=$('courseGrid');g.innerHTML='';Object.keys(TOPICS).forEach(c=>{const d=document.createElement('button');d.className='card course-card';d.innerHTML='<b>'+esc(c)+'</b><span>'+TOPICS[c].length+' topics • '+TOPICS[c].reduce((n,t)=>n+QUESTIONS.filter(q=>q.course===c&&q.topic===t).length,0)+' questions</span>';d.onclick=()=>openCourse(c);g.appendChild(d)});$('questionCount').textContent=QUESTIONS.length}
function openCourse(c){state.course=c;$('topicTitle').textContent=c+' Topics';const g=$('topicGrid');g.innerHTML='';const allBtn=document.createElement('button');allBtn.className='topic-card all-topic';allBtn.innerHTML='<b>All Topics</b><span>'+QUESTIONS.filter(q=>q.course===c).length+' questions across the course</span>';allBtn.onclick=()=>openSetup(c,'__ALL__');g.appendChild(allBtn);TOPICS[c].forEach(t=>{const n=QUESTIONS.filter(q=>q.course===c&&q.topic===t).length;const b=document.createElement('button');b.className='topic-card';b.innerHTML='<b>'+esc(t)+'</b><span>'+n+' questions</span>';b.onclick=()=>openSetup(c,t);g.appendChild(b)});showPage('topicsPage')}
function openSetup(c,t){state.course=c;state.topic=t;const label=t==='__ALL__'?'All Topics':t;const count=QUESTIONS.filter(q=>q.course===c&&(t==='__ALL__'||q.topic===t)).length;$('setupInfo').textContent=`${c} • ${label} • ${count} questions available`;showPage('setupPage')}
function shuffle(a){const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}
function startTest(){const limit=$('questionLimit').value;const all=QUESTIONS.filter(q=>q.course===state.course&&(state.topic==='__ALL__'||q.topic===state.topic));state.questions=shuffle(all).slice(0,limit==='all'?all.length:Number(limit));state.answers=Array(state.questions.length).fill(null);state.index=0;const custom=Number($('customMinutes').value||0); state.seconds=custom>0?custom*60:Number($('timePerQuestion').value)*state.questions.length;state.lastResult=null;showPage('testPage');$('testCourse').textContent=state.course;$('testTopic').textContent=state.topic;renderQuestion();startTimer()}
function startTimer(){if(state.timer)clearInterval(state.timer);updateTimer();state.timer=setInterval(()=>{state.seconds--;updateTimer();if(state.seconds<=0)finishTest(true)},1000)}
function updateTimer(){const m=Math.floor(state.seconds/60).toString().padStart(2,'0'),s=(state.seconds%60).toString().padStart(2,'0');$('timer').textContent=`${m}:${s}`;$('timer').classList.toggle('warning',state.seconds<=60)}
function renderQuestion(){const q=state.questions[state.index];$('qNumber').textContent=`Question ${state.index+1} of ${state.questions.length}`;$('qDifficulty').textContent=q.d;$('questionText').textContent=q.q;const opts=$('options');opts.innerHTML='';q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='option';b.innerHTML=`<span>${String.fromCharCode(65+i)}</span><strong>${esc(o)}</strong>`;if(state.answers[state.index]===i)b.classList.add('selected');b.onclick=()=>selectAnswer(i);opts.appendChild(b)});$('prevBtn').disabled=state.index===0;$('nextBtn').textContent=state.index===state.questions.length-1?'Finish':'Next →';$('submitBtn').classList.toggle('hidden',state.index!==state.questions.length-1);$('progressBar').style.width=((state.index+1)/state.questions.length*100)+'%'}
function selectAnswer(i){state.answers[state.index]=i;renderQuestion()}
function nextQuestion(){if(state.index<state.questions.length-1){state.index++;renderQuestion()}else finishTest(false)}
function prevQuestion(){if(state.index>0){state.index--;renderQuestion()}}
function finishTest(auto){if(state.timer){clearInterval(state.timer);state.timer=null};const correct=state.answers.reduce((n,a,i)=>n+(a===state.questions[i].a?1:0),0);const unanswered=state.answers.filter(a=>a===null).length;const wrong=state.questions.length-correct-unanswered;const pct=Math.round(correct/state.questions.length*100);const grade=pct>=90?'Excellent':pct>=75?'Very Good':pct>=60?'Good':pct>=50?'Fair':'Needs Improvement';const custom=Number($('customMinutes').value||0); const totalAllowed=custom>0?custom*60:Number($('timePerQuestion').value)*state.questions.length; const elapsed=Math.max(0,totalAllowed-state.seconds);const result={date:new Date().toISOString(),name:session().name,email:session().email,course:state.course,topic:state.topic,total:state.questions.length,correct,wrong,unanswered,pct,grade,auto,timeUsed:elapsed,questions:state.questions.map((q,i)=>({id:q.id,answer:state.answers[i]}))};state.lastResult=result;const hist=JSON.parse(localStorage.getItem(RESULTS_KEY)||'[]');hist.unshift(result);localStorage.setItem(RESULTS_KEY,JSON.stringify(hist.slice(0,50)));$('resultTitle').textContent=grade;$('resultPercent').textContent=pct+'%';$('resultCorrect').textContent=correct;$('resultWrong').textContent=wrong;$('resultUnanswered').textContent=unanswered;$('resultTotal').textContent=state.questions.length;$('resultCourse').textContent=state.course;$('resultTopic').textContent=state.topic==='__ALL__'?'All Topics':state.topic;$('resultGrade').textContent=grade;$('resultTime').textContent=Math.floor(elapsed/60)+':'+String(elapsed%60).padStart(2,'0');$('resultMessage').innerHTML=`<strong>${esc(session().name)}</strong> • ${esc(state.course)} • ${state.topic==='__ALL__'?'All Topics':esc(state.topic)}<br>${correct} correct, ${wrong} wrong and ${unanswered} unanswered. ${auto?'The timer reached zero and the test was submitted automatically.':''}`;showPage('resultsPage')}
function renderReview(){const r=state.lastResult;if(!r)return;const map=new Map(state.questions.map(q=>[q.id,q]));$('reviewList').innerHTML=state.questions.map((q,i)=>{const sel=state.answers[i];const ok=sel===q.a;return `<article class="review-item"><h3>${i+1}. ${esc(q.q)}</h3><p><b>Your answer:</b> ${sel===null?'Not answered':esc(q.o[sel])}</p><p class="${ok?'good':'bad'}"><b>Correct answer:</b> ${esc(q.o[q.a])}</p><p>${esc(q.e)}</p></article>`}).join('')}
function updateStats(){const hist=JSON.parse(localStorage.getItem(RESULTS_KEY)||'[]');const mine=hist.filter(x=>x.email===session()?.email);$('testsDone').textContent=mine.length;$('avgScore').textContent=(mine.length?Math.round(mine.reduce((s,x)=>s+x.pct,0)/mine.length):0)+'%';$('bestScore').textContent=(mine.length?Math.max(...mine.map(x=>x.pct)):0)+'%'}
function renderHistory(){const mine=JSON.parse(localStorage.getItem(RESULTS_KEY)||'[]').filter(x=>x.email===session()?.email);$('historyList').innerHTML=mine.length?mine.map(x=>`<div class="history-item"><b>${esc(x.course)} • ${esc(x.topic)}</b><span>${x.pct}% — ${x.grade} — ${new Date(x.date).toLocaleString()}</span></div>`).join(''):'<p class="muted">No completed tests yet.</p>'}
function renderProfile(){const s=session();$('profileName').textContent=s.name;$('profileEmail').textContent='Local practice mode';$('avatar').textContent=s.name.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}

$('backCourses').onclick=()=>showPage('coursesPage');$('backTopics').onclick=()=>openCourse(state.course);$('startTest').onclick=startTest;$('prevBtn').onclick=prevQuestion;$('nextBtn').onclick=nextQuestion;$('submitBtn').onclick=()=>finishTest(false);$('reviewBtn').onclick=()=>{renderReview();showPage('reviewPage')};$('backResults').onclick=()=>showPage('resultsPage');$('retryBtn').onclick=()=>openSetup(state.course,state.topic);$('homeBtn').onclick=()=>showPage('dashboardPage');document.querySelectorAll('.bottom-nav button').forEach(b=>b.onclick=()=>showPage(b.dataset.page));document.querySelectorAll('[data-page]').forEach(b=>{if(!b.closest('.bottom-nav'))b.onclick=()=>showPage(b.dataset.page)});document.querySelectorAll('.course-card').forEach(b=>b.onclick=()=>openCourse(b.dataset.course));
$('showRegister').onclick=()=>showAuth('register');
$('showLogin').onclick=()=>showAuth('login');
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();const email=$('loginEmail').value.trim().toLowerCase();const password=$('loginPassword').value;const users=getUsers();const user=users[email];if(!user){$('loginError').textContent='No account found with that email.';return}const hash=await hashPassword(password);if(hash!==user.passwordHash){$('loginError').textContent='Incorrect email or password.';return}localStorage.setItem(SESSION_KEY,email);$('loginForm').reset();enterApp()});
$('logoutBtn').onclick=()=>{localStorage.removeItem(SESSION_KEY);state={course:null,topic:null,questions:[],answers:[],index:0,seconds:0,timer:null,lastResult:null};enterApp()};
$('registerForm').addEventListener('submit',async e=>{e.preventDefault();const name=$('registerName').value.trim();const email=$('registerEmail').value.trim().toLowerCase();const password=$('registerPassword').value;const confirm=$('registerConfirm').value;if(name.length<2){$('registerError').textContent='Please enter your full name.';return}if(password.length<6){$('registerError').textContent='Password must be at least 6 characters.';return}if(password!==confirm){$('registerError').textContent='Passwords do not match.';return}const users=getUsers();if(users[email]){$('registerError').textContent='An account with this email already exists.';return}users[email]={name,email,passwordHash:await hashPassword(password)};saveUsers(users);localStorage.setItem(SESSION_KEY,email);$('registerForm').reset();enterApp()});
enterApp();
